-- 02_verbs_part1.sql  (part 1 of 4: verbs 1 to 516 of 2062)
-- Conjugation tables for the verbs in vocabulary.csv. Run 01_conjugations.sql first; run all 4 parts in any order.
-- Safe to run more than once: a verb that is already there is updated, nothing is removed.

on conflict (inf) do update set
    english = excluded.english, ending = excluded.ending, grp = excluded.grp, pronominal = excluded.pronominal,
    aux = excluded.aux, pp = excluded.pp, forms = excluded.forms, note = excluded.note;

-- Check: verbs in the table so far
select count(*) as verbs_so_far from "French-schema".conjugation_verbs;
